class Navigation:
    """Assert and follow the registered relationships. Mixed into Client; every call is one route."""

    def part_of(self, subject, entity, *, statement: str, command_id: str | None = None) -> dict[str, Any]:
        """Assert part-of (structural) between two entities; evidence: a statement by you."""
        return self._associate('part-of', {'kind': self.entity(subject).kind, 'entity_id': getattr(subject, "entity_id", subject)}, entity, {'statement': statement}, command_id)

    def parts(self, entity, **filters) -> list[Entity]:
        """Follow part-of backwards from an entity (the inverse the registry names: parts)."""
        return self._follow('part-of', entity, **filters)

    def of_entity(self, asset: str, revision: str, entity, *, row=None, source=None, statement: str | None = None, command_id: str | None = None) -> dict[str, Any]:
        """Assert of-entity (data-association) from this exact revision (or one row of it) to an entity; evidence: source-revision (default: the revision itself).

        Parameters
        ----------
        asset : str
            The item's id.
        revision : str
            The exact version the association starts from.
        entity
            The well or wellbore (an `Entity`, its id, or {kind, entity_id}) it points to.
        row : optional
            One row of the revision, when the association names only that row.
        source : optional
            The exact version that is the evidence, {'asset_id', 'revision'}; the revision itself when None.
        statement : str, optional
            Your own words, kept with the evidence.
        command_id : str, optional
            Sent again, the same id answers with the same association.

        Returns
        -------
        dict
            The association as served (entities/associate).
        """
        source = source or {'asset_id': asset, 'revision': revision}
        evidence = {'source': dict(source), **({'statement': statement} if statement else {})}
        return self._associate('of-entity', {'kind': 'revision', 'asset_id': asset, 'revision': revision, **({'row': row} if row else {})}, entity, evidence, command_id)

    def data(self, entity, **filters) -> list[dict[str, Any]]:
        """Follow of-entity backwards from an entity (the inverse the registry names: data)."""
        return self._follow('of-entity', entity, **filters)
